-- ICT371 Question 6: Monthly Payroll Processing (MySQL 8.0)
CREATE DATABASE IF NOT EXISTS ict371_q06_payroll; USE ict371_q06_payroll;
CREATE TABLE employees(employee_id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,basic_salary DECIMAL(12,2) NOT NULL CHECK(basic_salary>=0),allowance DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(allowance>=0),deduction DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(deduction>=0),active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE payroll(payroll_id BIGINT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,pay_month DATE NOT NULL,gross_pay DECIMAL(12,2) NOT NULL,net_pay DECIMAL(12,2) NOT NULL,UNIQUE KEY uq_payroll_employee_month(employee_id,pay_month),FOREIGN KEY(employee_id) REFERENCES employees(employee_id),CHECK(DAY(pay_month)=1));
CREATE TABLE salary_audit(audit_id BIGINT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,old_salary DECIMAL(12,2) NOT NULL,new_salary DECIMAL(12,2) NOT NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES employees(employee_id));
CREATE TABLE payroll_job_runs(run_id BIGINT AUTO_INCREMENT PRIMARY KEY,run_started_at DATETIME NOT NULL,processed_month DATE NOT NULL,run_status ENUM('SUCCEEDED','FAILED') NOT NULL,error_text VARCHAR(500) NULL);
INSERT INTO employees(full_name,basic_salary,allowance,deduction,active) VALUES('Nalia Chanda',6000,500,300,TRUE),('Bwalya Mwila',4500,350,200,TRUE),('Kunda Phiri',5200,0,500,TRUE),('Tembo Banda',3900,250,150,FALSE);
DELIMITER $$
CREATE FUNCTION fn_net_pay(p_employee_id INT) RETURNS DECIMAL(12,2) DETERMINISTIC READS SQL DATA BEGIN DECLARE v_basic DECIMAL(12,2); DECLARE v_allow DECIMAL(12,2); DECLARE v_deduct DECIMAL(12,2); SELECT basic_salary,allowance,deduction INTO v_basic,v_allow,v_deduct FROM employees WHERE employee_id=p_employee_id; IF v_basic IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Unknown employee'; END IF; IF v_basic+v_allow-v_deduct<0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Computed net pay is negative'; END IF; RETURN v_basic+v_allow-v_deduct; END$$
CREATE TRIGGER trg_salary_audit AFTER UPDATE ON employees FOR EACH ROW BEGIN IF NOT(OLD.basic_salary<=>NEW.basic_salary) THEN INSERT INTO salary_audit(employee_id,old_salary,new_salary) VALUES(NEW.employee_id,OLD.basic_salary,NEW.basic_salary); END IF; END$$
CREATE PROCEDURE pr_process_payroll(IN p_month DATE) BEGIN DECLARE done INT DEFAULT 0; DECLARE v_id INT; DECLARE v_basic DECIMAL(12,2); DECLARE v_allow DECIMAL(12,2); DECLARE v_net DECIMAL(12,2); DECLARE c CURSOR FOR SELECT employee_id,basic_salary,allowance FROM employees WHERE active=TRUE ORDER BY employee_id; DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=1; DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; IF p_month IS NULL OR DAY(p_month)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='pay_month must be first day of month'; END IF; START TRANSACTION; OPEN c; payroll_loop: LOOP FETCH c INTO v_id,v_basic,v_allow; IF done THEN LEAVE payroll_loop; END IF; SET v_net=fn_net_pay(v_id); INSERT INTO payroll(employee_id,pay_month,gross_pay,net_pay) VALUES(v_id,p_month,v_basic+v_allow,v_net) ON DUPLICATE KEY UPDATE payroll_id=payroll_id; END LOOP; CLOSE c; COMMIT; END$$
CREATE PROCEDURE pr_run_payroll_job(IN p_month DATE) BEGIN CALL pr_process_payroll(p_month); INSERT INTO payroll_job_runs(run_started_at,processed_month,run_status) VALUES(NOW(),p_month,'SUCCEEDED'); END$$
DELIMITER ;
INSERT INTO payroll(employee_id,pay_month,gross_pay,net_pay) VALUES(1,'2026-09-01',6500,6200),(2,'2026-09-01',4850,4650),(1,'2026-10-01',6500,6200),(2,'2026-10-01',4850,4650);
CREATE VIEW v_payroll_report AS SELECT e.employee_id,e.full_name,p.pay_month,p.gross_pay,p.net_pay FROM employees e JOIN payroll p ON p.employee_id=e.employee_id;
CREATE INDEX ix_payroll_month ON payroll(pay_month);
EXPLAIN SELECT employee_id,gross_pay,net_pay FROM payroll WHERE pay_month='2026-10-01';
SET GLOBAL event_scheduler=ON; CREATE EVENT IF NOT EXISTS ev_process_monthly_payroll ON SCHEDULE EVERY 1 MONTH STARTS (TIMESTAMP(DATE_FORMAT(CURRENT_DATE+INTERVAL 1 MONTH,'%Y-%m-01'),'02:00:00')) DO CALL pr_run_payroll_job(DATE_FORMAT(CURRENT_DATE-INTERVAL 1 MONTH,'%Y-%m-01'));
-- Inspect scheduled job metadata and the application-maintained successful run history.
SELECT EVENT_NAME,STATUS,LAST_EXECUTED,INTERVAL_VALUE,INTERVAL_FIELD FROM information_schema.EVENTS WHERE EVENT_SCHEMA=DATABASE() AND EVENT_NAME='ev_process_monthly_payroll';
SELECT * FROM payroll_job_runs ORDER BY run_id DESC;
